import{c as d,Q as e,j as r,m as n}from"./chunks/framework.rWdQudnF.js";const P=JSON.parse('{"title":"架构师-备考 综合知识-网络与安全-网络协议","description":"","frontmatter":{"title":"架构师-备考 综合知识-网络与安全-网络协议"},"headers":[],"relativePath":"综合知识/网络与安全/网络协议.md","filePath":"综合知识/网络与安全/网络协议.md","lastUpdated":null}'),o={name:"综合知识/网络与安全/网络协议.md"};function s(a,t,l,g,i,h){return e(),r("div",null,[...t[0]||(t[0]=[n('<h3 id="应用层协议速查" tabindex="-1">应用层协议速查 <a class="header-anchor" href="#应用层协议速查" aria-label="Permalink to &quot;应用层协议速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th style="text-align:center;">端口</th><th>功能</th><th style="text-align:center;">传输</th></tr></thead><tbody><tr><td>HTTP</td><td style="text-align:center;">80</td><td>超文本传输（Web）</td><td style="text-align:center;">TCP</td></tr><tr><td>HTTPS</td><td style="text-align:center;">443</td><td>HTTP over SSL，加密传输</td><td style="text-align:center;">TCP</td></tr><tr><td>FTP</td><td style="text-align:center;">20数据/21控制</td><td>文件传输</td><td style="text-align:center;">TCP</td></tr><tr><td>TFTP</td><td style="text-align:center;">69</td><td>简单文件传输</td><td style="text-align:center;">UDP</td></tr><tr><td>SMTP</td><td style="text-align:center;">25</td><td>邮件<strong>发送</strong></td><td style="text-align:center;">TCP</td></tr><tr><td>POP3</td><td style="text-align:center;">110</td><td>邮件<strong>接收</strong></td><td style="text-align:center;">TCP</td></tr><tr><td>DNS</td><td style="text-align:center;">53</td><td>域名→IP解析</td><td style="text-align:center;">UDP为主</td></tr><tr><td>DHCP</td><td style="text-align:center;">67服务端/68客户端</td><td>动态分配IP</td><td style="text-align:center;">UDP</td></tr><tr><td>Telnet</td><td style="text-align:center;">23</td><td>远程登录（明文）</td><td style="text-align:center;">TCP</td></tr><tr><td>SNMP</td><td style="text-align:center;">161轮询/162陷阱</td><td>网络管理</td><td style="text-align:center;">UDP</td></tr></tbody></table><hr><h3 id="传输层-tcp-vs-udp" tabindex="-1">传输层：TCP vs UDP <a class="header-anchor" href="#传输层-tcp-vs-udp" aria-label="Permalink to &quot;传输层：TCP vs UDP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td><strong>连接方式</strong></td><td>面向连接</td><td>无连接</td></tr><tr><td><strong>可靠性</strong></td><td>可靠（重发机制、确认）</td><td>不可靠</td></tr><tr><td><strong>传输方式</strong></td><td>基于字节流</td><td>基于数据报</td></tr><tr><td><strong>额外功能</strong></td><td>流量控制、拥塞控制</td><td>无</td></tr><tr><td><strong>效率</strong></td><td>较低</td><td>高、延迟小</td></tr><tr><td><strong>适用场景</strong></td><td>数据量小、可靠性要求高（HTTP/FTP/SMTP）</td><td>数据量大、实时性要求高（音视频/DNS/DHCP）</td></tr></tbody></table><blockquote><p>口诀：<strong>TCP可靠UDP快，连接与否是关键。网页邮件用TCP，音视频查询UDP带。</strong></p></blockquote><hr><h3 id="网际层协议" tabindex="-1">网际层协议 <a class="header-anchor" href="#网际层协议" aria-label="Permalink to &quot;网际层协议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>功能</th></tr></thead><tbody><tr><td><strong>IP</strong></td><td>核心协议，无连接、不可靠的数据报传送和路由选择</td></tr><tr><td><strong>ICMP</strong></td><td>控制报文协议，传递网络状态信息（ping 使用 ICMP Echo）</td></tr><tr><td><strong>ARP</strong></td><td>地址解析：<strong>IP地址 → MAC物理地址</strong></td></tr><tr><td><strong>RARP</strong></td><td>反向解析：MAC → IP（已被DHCP取代）</td></tr><tr><td><strong>IGMP</strong></td><td>网络组管理，支持组播</td></tr></tbody></table><blockquote><p>口诀：<strong>IP寻址和路由，ICMP管诊断。ARP找MAC，组播就找IGMP。</strong></p></blockquote><hr><h3 id="ip-地址" tabindex="-1">IP 地址 <a class="header-anchor" href="#ip-地址" aria-label="Permalink to &quot;IP 地址&quot;">​</a></h3><blockquote><p>IP 地址是 32 位二进制代码，采用<strong>点分十进制</strong>表示，每 8 位转为十进制（0~255）。</p></blockquote><p><strong>分类 IP 地址：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">类别</th><th>首字节范围</th><th style="text-align:center;">网络号位数</th><th>默认掩码</th><th>适用</th></tr></thead><tbody><tr><td style="text-align:center;">A</td><td>1~126</td><td style="text-align:center;">8</td><td>255.0.0.0</td><td>大型网络</td></tr><tr><td style="text-align:center;">B</td><td>128~191</td><td style="text-align:center;">16</td><td>255.255.0.0</td><td>中型网络</td></tr><tr><td style="text-align:center;">C</td><td>192~223</td><td style="text-align:center;">24</td><td>255.255.255.0</td><td>小型网络</td></tr><tr><td style="text-align:center;">D</td><td>224~239</td><td style="text-align:center;">—</td><td>—</td><td>多播</td></tr><tr><td style="text-align:center;">E</td><td>240~255</td><td style="text-align:center;">—</td><td>—</td><td>保留</td></tr></tbody></table><p><strong>私有地址范围：</strong></p><ul><li>A类：10.0.0.0 ~ 10.255.255.255</li><li>B类：172.16.0.0 ~ 172.31.255.255</li><li>C类：192.168.0.0 ~ 192.168.255.255</li></ul><p><strong>无分类编址（CIDR）</strong>：格式 <code>IP地址/网络号位数</code>，如 <code>128.168.0.11/20</code> 表示网络号占 20 位。</p><p><strong>子网划分：</strong> IP → 网络号 + 子网号 + 主机号；子网掩码 = 网络号和子网号全为 1、主机号全为 0。<strong>主机号不能为全 0 或全 1</strong>（主机数需 -2），子网号可以为全 0 和全 1。</p><p><strong>超网</strong>：子网划分的逆过程，将网络号取出几位作为主机号，扩大主机数量。</p><hr><h3 id="ipv6" tabindex="-1">IPv6 <a class="header-anchor" href="#ipv6" aria-label="Permalink to &quot;IPv6&quot;">​</a></h3><blockquote><p>IPv6 地址长度 <strong>128 位</strong>，地址空间增大 2^96 倍。</p></blockquote><p><strong>特性</strong>：灵活报文头部、简化头部格式加快转发、提高安全性（身份认证和隐私权）、支持更多服务类型。</p><p><strong>IPv4→IPv6 过渡三种技术：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td><strong>双协议栈</strong></td><td>主机同时运行 IPv4 和 IPv6 两套协议栈，IPv6 低 32 位可直接转为 IPv4 地址</td></tr><tr><td><strong>隧道技术</strong></td><td>在 IPv4 网络上建立传输 IPv6 数据报的隧道，IPv6 数据报封装在 IPv4 数据报中</td></tr><tr><td><strong>翻译技术</strong></td><td>利用专门翻译设备在纯 IPv4 和纯 IPv6 网络间转换 IP 报头地址</td></tr></tbody></table><hr><h3 id="网络新技术与概念" tabindex="-1">网络新技术与概念 <a class="header-anchor" href="#网络新技术与概念" aria-label="Permalink to &quot;网络新技术与概念&quot;">​</a></h3><p><strong>NAT（网络地址翻译）</strong>：将大量内部地址集合映射到少量外部公网 IP 地址，减少 IP 地址使用量。</p><p><strong>VLAN（虚拟局域网）</strong>：一组逻辑上的设备和用户，不受物理位置限制。<strong>一个 VLAN 就是一个广播域</strong>，VLAN 间通信通过路由器完成。优点：减少管理开销、控制广播、提高安全性。</p><p><strong>VPN（虚拟专用网）</strong>：在公用网络上建立专用网络，任意两节点间没有传统专网所需的端到端物理链路，通过逻辑链路传输数据。</p><p><strong>PPP 认证</strong>：</p><ul><li>PAP：二次握手，明文不加密</li><li>CHAP：三次握手，密文 MD5 加密</li></ul><p><strong>5G 关键特征</strong>：服务化架构、<strong>网络切片</strong>（将物理网络划分为多个逻辑独立的虚拟网络）。</p><p><strong>网络切片相关技术：</strong></p><ul><li><strong>SDN</strong>：关键使能技术，实现网络切片灵活控制</li><li><strong>NFV</strong>：关键使能技术，实现网络切片功能虚拟化，硬件与软件解耦</li><li><strong>边缘计算</strong>：互补技术，常依托特定网络切片（如 uRLLC 切片）部署</li></ul><hr><h3 id="网络存储技术" tabindex="-1">网络存储技术 <a class="header-anchor" href="#网络存储技术" aria-label="Permalink to &quot;网络存储技术&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>特点</th></tr></thead><tbody><tr><td><strong>DAS</strong>（直接附加存储）</td><td>存储设备通过 SCSI 接口直接连接服务器，无存储操作系统，容量难扩展</td></tr><tr><td><strong>NAS</strong>（网络附加存储）</td><td>通过网络接口直连，独立存储系统，<strong>小文件级共享存取</strong>，即插即用</td></tr><tr><td><strong>SAN</strong>（存储区域网）</td><td>通过专用交换机连接，<strong>块（block）级别存储</strong>，从以太网中分离出独立存储网络</td></tr></tbody></table><p><strong>RAID（磁盘冗余阵列）速查：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>特点</th><th style="text-align:center;">利用率</th></tr></thead><tbody><tr><td style="text-align:center;">RAID0</td><td>数据分散存储，无冗余，速度最快</td><td style="text-align:center;">100%</td></tr><tr><td style="text-align:center;">RAID1</td><td>成对磁盘互为备份，可靠性高</td><td style="text-align:center;">50%</td></tr><tr><td style="text-align:center;">RAID2</td><td>数据条块化 + 海明码校验</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">RAID3</td><td>奇偶校验，单块磁盘存储校验信息</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">RAID5</td><td>交叉存储数据和奇偶校验，分布式存储校验信息</td><td style="text-align:center;">(n-1)/n</td></tr><tr><td style="text-align:center;">RAID0+1</td><td>两个 RAID0，一个磁盘损坏则当前 RAID0 无法工作</td><td style="text-align:center;">50%</td></tr><tr><td style="text-align:center;">RAID1+0</td><td>两个 RAID1，不允许同一组两个磁盘同时损坏，安全性更高</td><td style="text-align:center;">50%</td></tr></tbody></table><hr><h3 id="网络性能指标" tabindex="-1">网络性能指标 <a class="header-anchor" href="#网络性能指标" aria-label="Permalink to &quot;网络性能指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td><strong>速率</strong>（数据率/比特率）</td><td>数字信道上传送数据的速率，单位 b/s</td></tr><tr><td><strong>带宽</strong></td><td>通信线路传送数据的能力，单位时间内最高数据率</td></tr><tr><td><strong>吞吐量</strong></td><td>单位时间内通过某网络的数据量，受带宽限制</td></tr><tr><td><strong>时延</strong></td><td>发送时延 + 传播时延 + 处理时延 + 排队时延</td></tr><tr><td><strong>往返时间（RTT）</strong></td><td>发送方发数据到收到确认的总时间</td></tr><tr><td><strong>利用率</strong></td><td>信道利用率（信道被利用的概率）+ 网络利用率</td></tr></tbody></table><blockquote><p>服务器延迟主要影响因素：<strong>队列延迟</strong> + <strong>磁盘 I/O 延迟</strong>。路由器延迟通常<strong>大于</strong>交换机延迟（路由器需做更多处理）。</p></blockquote><hr><h3 id="dns-配置相关" tabindex="-1">DNS 配置相关 <a class="header-anchor" href="#dns-配置相关" aria-label="Permalink to &quot;DNS 配置相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>/etc/resolv.conf</code></td><td>DNS 客户端配置文件，定义 DNS 服务器 IP 和域名搜索顺序</td></tr><tr><td><code>/etc/hosts</code></td><td>静态域名解析文件，优先级通常高于 DNS</td></tr><tr><td><code>/etc/nsswitch.conf</code></td><td>名称服务切换配置，决定解析顺序（如 <code>hosts: files dns</code>）</td></tr><tr><td><code>/etc/hostname</code></td><td>设置系统静态主机名</td></tr></tbody></table>',48)])])}const b=d(o,[["render",s]]);export{P as __pageData,b as default};
